// === Tab: mySketch ===
let simplex

function setup() {
	createCanvas(windowWidth, windowHeight);
	rs = random(1000)
	simplex = new OpenSimplexNoise(Date.now());
}

function draw() {
	background(255);
	//stem
	noStroke()
	for (let y = height + height / 8; y > height * 0.8; y -= 1) {
		let filler = map(y, height + height / 8, height * 0.8, 18, 0)
		fill(0, filler)
		ellipse(width / 2, y, height / 20, height / 30)
	}
	//leaves
	for (let i = 0; i < 0.5; i += 0.05) {
		let petalYPoint = map(simplex.noise2D(millis() / 2000, i/100), -1, 1, height, height * 0.76)
		let midPetalY = map(simplex.noise2D(millis() / 2000,  + 0.2), 0, 1, height * (0.8 +i/5), height * 0.66)
		let midPetalY2 = map(simplex.noise2D(millis() / 2000,  + 0.2), 0, 1, height * (0.8+i/5), height * 0.66)
		fill(0, 30)
		//ellipse(width * 0.15, petalYPoint, 20)
		//ellipse(width * 0.85, petalYPoint, 20)

		//left leaf
		beginShape()
		curveVertex(width / 2 - height / 18, height)

		curveVertex(width / 2 - height / 15, height)
		curveVertex(width* 0.25, midPetalY - height / 10)
		curveVertex(width * 0.1, petalYPoint)
		curveVertex(width*0.25, midPetalY2)



		curveVertex(width / 2 - height / 8, height + height / 10)
		endShape(CLOSE)


		//right leaf
		beginShape()
		curveVertex(width / 2 + height / 18, height)
		curveVertex(width / 2 + height / 15, height)
		curveVertex(width* 0.75, midPetalY - height / 10)
		curveVertex(width * 0.9, petalYPoint)
		curveVertex(width*0.75, midPetalY2)

		curveVertex(width / 2 + height / 8, height + height / 10)
		endShape(CLOSE)

	}

	//flower
	fill(0, 30)
	noStroke()
	for (let j = 0; j < 16; j += 0.5) {
		push()
		translate(width / 2, height / 2)
		rotate(j)
		beginShape()
		let d = map(simplex.noise2D(j / 3, millis() / 2000), -1, 1, height / 3, height / 2)
		let inc = TWO_PI / 13
		for (let i = 0; i <= TWO_PI; i += inc) {
			let xer = cos(i) * d
			let yer = sin(i) * d
			let midxer = cos(i + inc / 2) * (d / 3)
			let midyer = sin(i + inc / 2) * (d / 3)
			curveVertex(xer, yer)
			curveVertex(midxer, midyer)
		}
		curveVertex(cos(0) * d, sin(0) * d)
		endShape()
		pop()
	}
}

